#!/bin/bash

#===============================================
# LICENSE PROTECTED SCRIPT
# Product: Product A
# Generated by: License Manager
# API: http://192.168.8.169:3000/api/validate
# DO NOT MODIFY THIS SECTION
#===============================================

__PRODUCT_ID="1"
__API_URL="http://192.168.8.169:3000/api/validate"
__WELCOME_MSG="Welcome"
__SUPPORT_CONTACT="support@excellent.co.id"
__CHECK_EXPIRY=true
__CHECK_ACTIVATION=true
__CHECK_MACHINE=true
__SHOW_INFO=true

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Print header
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo " ${__WELCOME_MSG}"
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo ""

# Ask for license key
read -p "Enter your license key: " LICENSE_KEY

# Trim whitespace
LICENSE_KEY=$(echo "$LICENSE_KEY" | xargs)

# Validate not empty
if [ -z "$LICENSE_KEY" ]; then
  echo -e "${RED}✗ License key is required${NC}"
  exit 1
fi

echo ""
echo "Validating license..."

# Get machine ID (for machine binding)
MACHINE_ID=$(cat /etc/machine-id 2>/dev/null || hostid)

# Prepare JSON payload (without jq dependency)
JSON_PAYLOAD="{\"licenseKey\":\"$LICENSE_KEY\",\"productId\":\"$__PRODUCT_ID\",\"machineId\":\"$MACHINE_ID\",\"checkExpiry\":$__CHECK_EXPIRY,\"checkActivation\":$__CHECK_ACTIVATION,\"checkMachine\":$__CHECK_MACHINE}"

# Call API
RESPONSE=$(curl -s -X POST "$__API_URL" \
  -H "Content-Type: application/json" \
  -d "$JSON_PAYLOAD" \
  2>/dev/null)

# Check curl success
if [ $? -ne 0 ]; then
  echo -e "${RED}✗ Cannot connect to license server${NC}"
  echo -e "  Please check your internet connection"
  echo -e "  Contact: ${__SUPPORT_CONTACT}"
  exit 1
fi

# Parse JSON response (without jq - using grep and sed)
IS_VALID=$(echo "$RESPONSE" | grep -o '"valid"[[:space:]]*:[[:space:]]*true')
ERROR_MSG=$(echo "$RESPONSE" | grep -o '"message"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/"message"[[:space:]]*:[[:space:]]*"\(.*\)"/\1/')

# Check validation result
if [ -z "$IS_VALID" ]; then
  echo -e "${RED}✗ License validation failed${NC}"
  if [ -n "$ERROR_MSG" ]; then
    echo -e "  Reason: $ERROR_MSG"
  fi
  echo -e "  Contact: ${__SUPPORT_CONTACT}"
  exit 1
fi

# Success!
echo -e "${GREEN}✓ License valid${NC}"

# Show license info if enabled
if [ "$__SHOW_INFO" = "true" ]; then
  PRODUCT_NAME=$(echo "$RESPONSE" | grep -o '"productName"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/"productName"[[:space:]]*:[[:space:]]*"\(.*\)"/\1/')
  CUSTOMER_NAME=$(echo "$RESPONSE" | grep -o '"customerName"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/"customerName"[[:space:]]*:[[:space:]]*"\(.*\)"/\1/')
  EXPIRES_AT=$(echo "$RESPONSE" | grep -o '"expiresAt"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/"expiresAt"[[:space:]]*:[[:space:]]*"\(.*\)"/\1/')

  [ -n "$PRODUCT_NAME" ] && echo -e "${BLUE}✓ Product: $PRODUCT_NAME${NC}"
  [ -n "$CUSTOMER_NAME" ] && echo -e "${BLUE}✓ Licensed to: $CUSTOMER_NAME${NC}"
  [ -n "$EXPIRES_AT" ] && echo -e "${BLUE}✓ Expires: $EXPIRES_AT${NC}"
fi

echo ""
echo "Starting script execution..."
echo ""

